def deadlock_cycle(wait_for):
    done, active, path = set(), {}, []
    def visit(thread):
        if thread in active:
            return path[active[thread]:] + [thread]
        if thread in done:
            return None
        active[thread] = len(path)
        path.append(thread)
        for owner in wait_for.get(thread, []):
            cycle = visit(owner)
            if cycle:
                return cycle
        path.pop()
        active.pop(thread)
        done.add(thread)
        return None
    for thread in wait_for:
        cycle = visit(thread)
        if cycle:
            return cycle
    return None

graph = {"A": ["B"], "B": ["C"], "C": ["A"], "D": ["A"]}
print(" -> ".join(deadlock_cycle(graph)))
graph["C"] = []
print("after release:", deadlock_cycle(graph))

class Receiver:
    def __init__(self):
        self.next_sequence = 0
        self.pending = {}
        self.delivered = bytearray()

    def receive(self, sequence, payload):
        for offset, byte in enumerate(payload):
            position = sequence + offset
            if position >= self.next_sequence:
                self.pending.setdefault(position, byte)
        while self.next_sequence in self.pending:
            byte = self.pending.pop(self.next_sequence)
            self.delivered.append(byte)
            self.next_sequence += 1
        return self.next_sequence

receiver = Receiver()
