import hashlib

class Origin:
    def __init__(self, body):
        self.body = body

    def get(self, if_none_match=None):
        encoded = self.body.encode("utf-8")
        etag = '"' + hashlib.sha256(encoded).hexdigest() + '"'
        headers = {"ETag": etag, "Cache-Control": "max-age=0"}
        if if_none_match == etag:
            return 304, headers, b""
        return 200, headers, encoded

origin = Origin("version one")
validator, cached = None, b""
for change in [None, None, "version two"]:
    if change is not None:
        origin.body = change
    status, headers, body = origin.get(validator)
    if status == 200:
        validator, cached = headers["ETag"], body
    print(status, "bytes", len(body), "cached", cached.decode())

