class Elevator:
    transitions = {
        ("idle", "open"): "doors_open",
        ("doors_open", "close"): "idle",
        ("idle", "move"): "moving",
        ("moving", "arrive"): "idle",
    }
    def __init__(self): self.state = "idle"
    def handle(self, event):
        next_state = self.transitions.get((self.state, event))
        if next_state is None:
            raise ValueError(f"{event} not allowed from {self.state}")
        self.state = next_state
        return self.state
