class Bucket:
    def __init__(self, capacity, rate):
        self.capacity, self.rate = capacity, rate
        self.tokens, self.last = float(capacity), 0.0
    def allow(self, now):
        if now < self.last: raise ValueError("clock moved backward")
        self.tokens = min(self.capacity, self.tokens + (now-self.last)*self.rate)
        self.last = now
        if self.tokens < 1: return False
        self.tokens -= 1
        return True
bucket = Bucket(2, 1)
for now in [0, 0, 0, 0.5, 1, 5]:
    print(now, bucket.allow(now))

class Ledger:
    def __init__(self):
        self.balances = {"A": 100, "B": 0}
        self.operations = {}
    def transfer(self, key, sender, recipient, cents):
        fingerprint = (sender, recipient, cents)
        if key in self.operations:
            previous, result = self.operations[key]
            if previous != fingerprint: raise ValueError("conflicting retry")
            return result
        if sender == recipient or cents <= 0: raise ValueError("invalid transfer")
        if self.balances[sender] < cents: raise ValueError("insufficient funds")
        self.balances[sender] -= cents
        self.balances[recipient] += cents
        result = "accepted"
        self.operations[key] = (fingerprint, result)
        return result
