import re

def words(text): return set(re.findall(r"[a-z]+", text.lower()))
def retrieve(user, query, documents, k=2):
    scored = []
    for doc in documents:
        if user not in doc["readers"]: continue
        score = len(words(query) & words(doc["text"]))
        if score: scored.append((-score, doc["id"], doc["text"]))
    return [(identity, text) for _, identity, text in sorted(scored)[:k]]
