    {"id": "private", "readers": {"Anish"}, "text": "Cache production credentials are confidential."},
]
for identity, text in retrieve("Brother", "cache production", documents):
    print(identity, text)

def dispatch(name, arguments):
    if name != "sum_numbers": raise ValueError("unknown tool")
    if not isinstance(arguments, dict) or set(arguments) != {"numbers"}:
        raise ValueError("expected only numbers")
    numbers = arguments["numbers"]
    if not isinstance(numbers, list) or len(numbers) > 100:
        raise ValueError("expected at most 100 numbers")
    if any(type(value) is not int for value in numbers):
        raise ValueError("integers required")
    return {"content": [{"type": "text", "text": str(sum(numbers))}]}
